"use client";

import { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { CheckCircle, AlertCircle, User, Phone, Mail, Lock } from "lucide-react";
import Layout from "../Layout";

export default function CreateChef() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    phoneNumber: "",
    email: "",
    password: "",
    grade: "Chef",
  });
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess("");
    setIsSubmitting(true);

    const token = localStorage.getItem("token");

    try {
      const response = await axios.post(
        `${process.env.REACT_APP_API_URL}/api/chefs`,
        formData,
        {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: "Superadmin",
          },
        }
      );

      setSuccess("Chef créé avec succès !");
      setTimeout(() => navigate("/Chefs"), 2000);
    } catch (err) {
      setError(err.response?.data?.message || "Une erreur s'est produite.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Layout>
      <div className="max-w-5xl mx-auto">
        <div className="bg-white rounded-xl shadow-xl overflow-hidden">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <h2 className="text-2xl font-bold tracking-tight">Créer un nouveau chef</h2>
            <p className="text-white/80 mt-1">Rôle: Chef (par défaut)</p>
          </div>

          {(error || success) && (
            <div
              className={`p-4 ${error ? "bg-red-50" : "bg-green-50"} border-l-4 ${
                error ? "border-red-500" : "border-green-500"
              } flex items-center gap-3`}
            >
              {error ? (
                <AlertCircle className="h-5 w-5 text-red-500" />
              ) : (
                <CheckCircle className="h-5 w-5 text-green-500" />
              )}
              <p className={`text-sm ${error ? "text-red-700" : "text-green-700"}`}>
                {error || success}
              </p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="p-6">
            <div className="space-y-8">
              <div>
                <h3 className="text-lg font-medium text-gray-900 border-b pb-2">Informations du chef</h3>
                <div className="mt-4 grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Prénom</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="firstName"
                        value={formData.firstName}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-[#00717F] focus:border-[#00717F]"
                        required
                      />
                      <User className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Nom</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="lastName"
                        value={formData.lastName}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-[#00717F] focus:border-[#00717F]"
                        required
                      />
                      <User className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Numéro de téléphone</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="phoneNumber"
                        value={formData.phoneNumber}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-[#00717F] focus:border-[#00717F]"
                        required
                      />
                      <Phone className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Email</label>
                    <div className="relative">
                      <input
                        type="email"
                        name="email"
                        value={formData.email}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-[#00717F] focus:border-[#00717F]"
                        required
                      />
                      <Mail className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Mot de passe</label>
                    <div className="relative">
                      <input
                        type="password"
                        name="password"
                        value={formData.password}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-[#00717F] focus:border-[#00717F]"
                        required
                      />
                      <Lock className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Grade</label>
                    <select
                      name="grade"
                      value={formData.grade}
                      onChange={handleChange}
                      className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-[#00717F] focus:border-[#00717F]"
                      required
                    >
                      <option value="Chef">Chef</option>
                      <option value="Sous Chef">Sous Chef</option>
                      <option value="Pastry Chef">Chef Pâtissier</option>
                      <option value="Line Cook">Cuisinier de ligne</option>
                    </select>
                  </div>
                </div>
              </div>
            </div>

            <div className="mt-8 flex justify-end">
              <button
                type="button"
                onClick={() => navigate("/Chefs")}
                className="px-5 py-3 border border-gray-300 text-gray-700 rounded-md shadow-sm hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#00717F] mr-3"
              >
                Annuler
              </button>
              <button
                type="submit"
                disabled={isSubmitting}
                className="px-5 py-3 bg-[#00717F] text-white rounded-md shadow-sm hover:bg-[#00717F]/90 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#00717F] flex items-center"
              >
                {isSubmitting ? (
                  <>
                    <svg
